insert into public.organizations (slug, name, description, published, directory_content) select 'experimental-aircraft-association-and-young-eagles', 'Experimental Aircraft Association & Young Eagles', 'Free introductory Young Eagles flights for ages 8–17, aviation education, ground-school benefits, events, scholarships, and a worldwide recreational aviation community.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/eaa.png","category":"","icon":"plane","id":"","kind":"organizations","slug":"experimental-aircraft-association-and-young-eagles","title":"Experimental Aircraft Association & Young Eagles","summary":"Free introductory Young Eagles flights for ages 8–17, aviation education, ground-school benefits, events, scholarships, and a worldwide recreational aviation community.","tags":["Youth flights","Education","Scholarships"],"info":{"officialUrl":"https://www.eaa.org/eaa/youth/free-ye-flights","sourceLabel":"EAA Young Eagles","overview":"EAA’s Young Eagles program introduces young people ages 8–17 to personal aviation through free flights with volunteer EAA pilots. After a flight, students can unlock additional learning and membership benefits.","highlights":["Free introductory flights for ages 8–17","Free student membership after a Young Eagles flight","Online ground-school and aviation-learning benefits","Local chapters, mentors, events, and scholarship pathways"],"nextSteps":["Find a nearby Young Eagles flight","Meet your local EAA chapter","Ask about youth programs and scholarships"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'experimental-aircraft-association-and-young-eagles' or name = 'Experimental Aircraft Association & Young Eagles'));
update public.organizations set directory_content = '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/eaa.png","category":"","icon":"plane","id":"","kind":"organizations","slug":"experimental-aircraft-association-and-young-eagles","title":"Experimental Aircraft Association & Young Eagles","summary":"Free introductory Young Eagles flights for ages 8–17, aviation education, ground-school benefits, events, scholarships, and a worldwide recreational aviation community.","tags":["Youth flights","Education","Scholarships"],"info":{"officialUrl":"https://www.eaa.org/eaa/youth/free-ye-flights","sourceLabel":"EAA Young Eagles","overview":"EAA’s Young Eagles program introduces young people ages 8–17 to personal aviation through free flights with volunteer EAA pilots. After a flight, students can unlock additional learning and membership benefits.","highlights":["Free introductory flights for ages 8–17","Free student membership after a Young Eagles flight","Online ground-school and aviation-learning benefits","Local chapters, mentors, events, and scholarship pathways"],"nextSteps":["Find a nearby Young Eagles flight","Meet your local EAA chapter","Ask about youth programs and scholarships"]}}'::jsonb where directory_content is null and (slug = 'experimental-aircraft-association-and-young-eagles' or name = 'Experimental Aircraft Association & Young Eagles');
insert into public.organizations (slug, name, description, published, directory_content) select 'aircraft-owners-and-pilots-association', 'Aircraft Owners and Pilots Association', 'Flight-training materials, safety education, scholarships, flying clubs, advocacy, and a large network for general aviation pilots and students.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/scholarship-logos/aopa.svg","category":"","icon":"plane","id":"","kind":"organizations","slug":"aircraft-owners-and-pilots-association","title":"Aircraft Owners and Pilots Association","summary":"Flight-training materials, safety education, scholarships, flying clubs, advocacy, and a large network for general aviation pilots and students.","tags":["Training","Safety","Community"],"info":{"officialUrl":"https://www.aopa.org/","sourceLabel":"AOPA","overview":"AOPA supports general aviation pilots and learners through safety education, flight-training resources, advocacy, events, flying-club information, and scholarships.","highlights":["Flight-training and student resources","Free safety courses and seminars","AOPA Foundation scholarships","Flying clubs and aviation community"],"nextSteps":["Explore AOPA’s student resources","Review the current scholarship cycle","Use safety courses as you begin training"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'aircraft-owners-and-pilots-association' or name = 'Aircraft Owners and Pilots Association'));
