insert into public.organizations (slug, name, description, published, directory_content) select 'civil-air-patrol', 'Civil Air Patrol', 'Aerospace education, leadership development, community service, emergency services, and flight opportunities through its cadet program.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/civil-air-patrol.png","category":"","icon":"plane","id":"","kind":"organizations","slug":"civil-air-patrol","title":"Civil Air Patrol","summary":"Aerospace education, leadership development, community service, emergency services, and flight opportunities through its cadet program.","tags":["Cadets","Leadership","Flight training"],"info":{"officialUrl":"https://www.gocivilairpatrol.com/programs/cadets","sourceLabel":"Civil Air Patrol","overview":"Civil Air Patrol’s cadet program combines aerospace education, leadership, physical fitness, character development, service, and access to aviation experiences.","highlights":["Aerospace education and orientation flights","Leadership progression and community service","Local squadrons across the United States","Cadet Wings and other flight-training opportunities"],"nextSteps":["Find a local squadron","Attend a prospective-member meeting","Ask about orientation flights and Cadet Wings"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'civil-air-patrol' or name = 'Civil Air Patrol'));
