insert into public.organizations (slug, name, description, published, directory_content) select 'junior-rotc', 'Junior ROTC', 'A high-school leadership and citizenship program that can provide aerospace education, service experience, and exposure to aviation careers.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/jrotc-official.png","category":"","icon":"plane","id":"","kind":"organizations","slug":"junior-rotc","title":"Junior ROTC","summary":"A high-school leadership and citizenship program that can provide aerospace education, service experience, and exposure to aviation careers.","tags":["High school","Leadership","Service"],"info":{"officialUrl":"https://www.usarmyjrotc.com/","sourceLabel":"U.S. Army Junior ROTC","overview":"Junior ROTC programs help high-school students develop leadership, citizenship, discipline, teamwork, and, in many units, exposure to aerospace education and aviation careers.","highlights":["School-based leadership development","Community service and team activities","Aerospace and aviation exposure in participating programs","No requirement to enter military service"],"nextSteps":["Ask whether your school offers JROTC","Review the program’s activities and expectations","Look for aviation or flight-focused opportunities"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'junior-rotc' or name = 'Junior ROTC'));
