insert into public.organizations (slug, name, description, published, directory_content) select 'aviation-career-education-academy', 'Aviation Career Education Academy', 'Hands-on workshops, field trips, mentorship, and flight experiences that introduce students to aviation and aerospace careers.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/faa.svg","category":"","icon":"plane","id":"","kind":"organizations","slug":"aviation-career-education-academy","title":"Aviation Career Education Academy","summary":"Hands-on workshops, field trips, mentorship, and flight experiences that introduce students to aviation and aerospace careers.","tags":["Hands-on","Mentorship","Careers"],"info":{"officialUrl":"https://www.faa.gov/education/ace_academy","sourceLabel":"FAA ACE Academies","overview":"FAA Aviation Career Education Academies introduce students to aviation careers through age-appropriate programs that may include airport visits, hands-on learning, speakers, and flight experiences.","highlights":["Career exploration for students","Hands-on aviation and STEM learning","Programs hosted in different regions","Exposure to pilots, engineers, airports, and aviation systems"],"nextSteps":["Check the FAA’s current academy listings","Review age and location requirements","Apply to a program near you"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'aviation-career-education-academy' or name = 'Aviation Career Education Academy'));
