insert into public.organizations (slug, name, description, published, directory_content) select 'academy-of-model-aeronautics', 'Academy of Model Aeronautics', 'Model aviation training, safety education, events, competitions, and a welcoming entry point into flight for learners of all ages.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/ama-official.png","category":"","icon":"plane","id":"","kind":"organizations","slug":"academy-of-model-aeronautics","title":"Academy of Model Aeronautics","summary":"Model aviation training, safety education, events, competitions, and a welcoming entry point into flight for learners of all ages.","tags":["Model aircraft","STEM","Events"],"info":{"officialUrl":"https://www.modelaircraft.org/","sourceLabel":"Academy of Model Aeronautics","overview":"The Academy of Model Aeronautics connects people through model aviation and provides education, safety guidance, clubs, competitions, and a practical introduction to aerodynamics and flight.","highlights":["Local model-aircraft clubs","STEM and youth education","Safety guidance and flying resources","Competitions, events, and community"],"nextSteps":["Find a local AMA club","Visit a flying event","Start with a beginner-friendly model or simulator"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'academy-of-model-aeronautics' or name = 'Academy of Model Aeronautics'));
