insert into public.organizations (slug, name, description, published, directory_content) select 'red-tailed-hawks-flying-club', 'Red-Tailed Hawks Flying Club', 'A Seattle-based community expanding aviation access through mentorship, workshops, flight experiences, and the FLY training program.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/scholarship-logos/red-tailed-hawks.webp","category":"","icon":"plane","id":"","kind":"organizations","slug":"red-tailed-hawks-flying-club","title":"Red-Tailed Hawks Flying Club","summary":"A Seattle-based community expanding aviation access through mentorship, workshops, flight experiences, and the FLY training program.","tags":["Community","Mentorship","Youth"],"info":{"officialUrl":"https://www.redtailedhawks.org/","sourceLabel":"Red-Tailed Hawks Flying Club","overview":"Red-Tailed Hawks Flying Club expands access to aviation through youth education, mentorship, community activities, and hands-on flight opportunities, with roots in the Seattle area.","highlights":["Youth aviation outreach","Mentoring and role models","Hands-on learning and flight experiences","A focus on access and representation"],"nextSteps":["Review current youth programs","Attend a community event","Ask about mentoring or flight-training opportunities"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'red-tailed-hawks-flying-club' or name = 'Red-Tailed Hawks Flying Club'));
