insert into public.organizations (slug, name, description, published, directory_content) select 'women-in-aviation-international', 'Women in Aviation International', 'Scholarships, conferences, mentoring, education, and a global network supporting women across aviation and aerospace.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"/organization-logos/women-in-aviation.png","category":"","icon":"plane","id":"","kind":"organizations","slug":"women-in-aviation-international","title":"Women in Aviation International","summary":"Scholarships, conferences, mentoring, education, and a global network supporting women across aviation and aerospace.","tags":["Women","Scholarships","Network"],"info":{"officialUrl":"https://www.wai.org/","sourceLabel":"Women in Aviation International","overview":"Women in Aviation International supports people across aviation and aerospace with chapters, conferences, scholarships, education, networking, and career development.","highlights":["Local and collegiate chapters","Annual scholarships","Mentoring and professional networking","Girls in Aviation Day and youth outreach"],"nextSteps":["Find a local chapter","Review scholarship opportunities","Attend an event or Girls in Aviation Day"]}}'::jsonb where not exists (select 1 from public.organizations where (slug = 'women-in-aviation-international' or name = 'Women in Aviation International'));
