insert into public.career_paths (slug, title, summary, published, directory_content) select 'professional-pilot-careers', 'Professional Pilot Careers', 'Explore airlines, regional carriers, corporate aviation, cargo, charter, medical transport, government service, firefighting, agriculture, air tours, test piloting, and spaceflight.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"professional-pilot-careers","title":"Professional Pilot Careers","summary":"Explore airlines, regional carriers, corporate aviation, cargo, charter, medical transport, government service, firefighting, agriculture, air tours, test piloting, and spaceflight.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/transportation-and-material-moving/airline-and-commercial-pilots.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Professional pilots fly and navigate airplanes, helicopters, and other aircraft in airline, charter, cargo, corporate, public-service, instructional, and specialized operations.","highlights":["Preflight planning and aircraft inspection","Weather, navigation, communication, and decision-making","FAA certificates, ratings, medical qualification, and experience","Schedules and training vary widely by employer"],"nextSteps":["Take a discovery flight","Learn the Student and Private Pilot certificate pathway","Compare local flight schools and aviation colleges"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'professional-pilot-careers' or title = 'Professional Pilot Careers'));
update public.career_paths set directory_content = '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"professional-pilot-careers","title":"Professional Pilot Careers","summary":"Explore airlines, regional carriers, corporate aviation, cargo, charter, medical transport, government service, firefighting, agriculture, air tours, test piloting, and spaceflight.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/transportation-and-material-moving/airline-and-commercial-pilots.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Professional pilots fly and navigate airplanes, helicopters, and other aircraft in airline, charter, cargo, corporate, public-service, instructional, and specialized operations.","highlights":["Preflight planning and aircraft inspection","Weather, navigation, communication, and decision-making","FAA certificates, ratings, medical qualification, and experience","Schedules and training vary widely by employer"],"nextSteps":["Take a discovery flight","Learn the Student and Private Pilot certificate pathway","Compare local flight schools and aviation colleges"]}}'::jsonb where directory_content is null and (slug = 'professional-pilot-careers' or title = 'Professional Pilot Careers');
insert into public.career_paths (slug, title, summary, published, directory_content) select 'drone-pilot', 'Drone Pilot', 'Use uncrewed aircraft for photography, inspection, mapping, public safety, and emerging commercial work. Paid operations generally require FAA Part 107 certification.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"code","id":"","kind":"careers","slug":"drone-pilot","title":"Drone Pilot","summary":"Use uncrewed aircraft for photography, inspection, mapping, public safety, and emerging commercial work. Paid operations generally require FAA Part 107 certification.","tags":[],"info":{"officialUrl":"https://www.faa.gov/newsroom/small-unmanned-aircraft-systems-uas-regulations-part-107","sourceLabel":"Federal Aviation Administration","overview":"Drone pilots use small uncrewed aircraft in photography, mapping, inspection, agriculture, public safety, research, and other commercial or government work.","highlights":["Commercial operations generally fall under FAA Part 107","Remote pilots must understand airspace and operating rules","A remote pilot certificate requires an FAA knowledge pathway","Technology and use cases continue to expand"],"nextSteps":["Learn recreational drone safety first","Study current Part 107 rules","Practice flight planning, weather, and airspace awareness"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'drone-pilot' or title = 'Drone Pilot'));
update public.career_paths set directory_content = '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"code","id":"","kind":"careers","slug":"drone-pilot","title":"Drone Pilot","summary":"Use uncrewed aircraft for photography, inspection, mapping, public safety, and emerging commercial work. Paid operations generally require FAA Part 107 certification.","tags":[],"info":{"officialUrl":"https://www.faa.gov/newsroom/small-unmanned-aircraft-systems-uas-regulations-part-107","sourceLabel":"Federal Aviation Administration","overview":"Drone pilots use small uncrewed aircraft in photography, mapping, inspection, agriculture, public safety, research, and other commercial or government work.","highlights":["Commercial operations generally fall under FAA Part 107","Remote pilots must understand airspace and operating rules","A remote pilot certificate requires an FAA knowledge pathway","Technology and use cases continue to expand"],"nextSteps":["Learn recreational drone safety first","Study current Part 107 rules","Practice flight planning, weather, and airspace awareness"]}}'::jsonb where directory_content is null and (slug = 'drone-pilot' or title = 'Drone Pilot');
insert into public.career_paths (slug, title, summary, published, directory_content) select 'flight-instructor', 'Flight Instructor', 'Teach new pilots, strengthen your own knowledge, and build experience toward advanced professional flying goals.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"careers","slug":"flight-instructor","title":"Flight Instructor","summary":"Teach new pilots, strengthen your own knowledge, and build experience toward advanced professional flying goals.","tags":[],"info":{"officialUrl":"https://www.faa.gov/pilots/become","sourceLabel":"Federal Aviation Administration","overview":"Certified Flight Instructors teach knowledge, procedures, decision-making, and aircraft control while helping students prepare for solos, certificates, ratings, and flight reviews.","highlights":["Requires advanced pilot knowledge and instructional skill","Builds communication, leadership, and judgment","Can help pilots accumulate professional experience","Different instructor ratings cover airplanes and instruments"],"nextSteps":["Begin with a Private Pilot Certificate","Progress through instrument and commercial training","Observe and learn from effective instructors"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'flight-instructor' or title = 'Flight Instructor'));
