insert into public.career_paths (slug, title, summary, published, directory_content) select 'air-traffic-control', 'Air Traffic Control', 'Direct aircraft safely in the air and on the ground using communication, radar, focus, and rapid decision-making.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"globe","id":"","kind":"careers","slug":"air-traffic-control","title":"Air Traffic Control","summary":"Direct aircraft safely in the air and on the ground using communication, radar, focus, and rapid decision-making.","tags":[],"info":{"officialUrl":"https://www.faa.gov/jobs/career_fields/aviation_careers","sourceLabel":"Federal Aviation Administration","overview":"Air traffic controllers coordinate aircraft movements to maintain safe separation and efficient traffic flow in airport towers, approach facilities, and en-route centers.","highlights":["Fast, precise communication","Strong focus and situational awareness","Specialized FAA hiring and training process","Shift work and high responsibility"],"nextSteps":["Review current FAA hiring requirements","Build math, communication, and decision-making skills","Learn how the national airspace system works"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'air-traffic-control' or title = 'Air Traffic Control'));
