insert into public.career_paths (slug, title, summary, published, directory_content) select 'airport-operations', 'Airport Operations', 'Keep an airfield safe and efficient through inspections, maintenance coordination, wildlife management, security, and emergency response.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"calendar","id":"","kind":"careers","slug":"airport-operations","title":"Airport Operations","summary":"Keep an airfield safe and efficient through inspections, maintenance coordination, wildlife management, security, and emergency response.","tags":[],"info":{"officialUrl":"https://www.faa.gov/airports","sourceLabel":"Federal Aviation Administration","overview":"Airport operations teams help keep airfields safe, secure, compliant, and ready for daily traffic and emergencies.","highlights":["Airfield inspections and condition reporting","Wildlife, snow, construction, and maintenance coordination","Emergency and security response","Coordination with airlines, tenants, and air traffic control"],"nextSteps":["Tour or volunteer at a local airport","Study airport management and safety","Look for airport internships or entry-level roles"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'airport-operations' or title = 'Airport Operations'));
