insert into public.career_paths (slug, title, summary, published, directory_content) select 'flight-dispatch', 'Flight Dispatch', 'Plan and monitor routes, evaluate weather and fuel needs, and coordinate between flight crews and operations teams.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"document","id":"","kind":"careers","slug":"flight-dispatch","title":"Flight Dispatch","summary":"Plan and monitor routes, evaluate weather and fuel needs, and coordinate between flight crews and operations teams.","tags":[],"info":{"officialUrl":"https://www.faa.gov/pilots/training/atp","sourceLabel":"Federal Aviation Administration","overview":"Aircraft dispatchers work with flight crews and operations teams to plan safe flights, evaluate weather and routes, calculate fuel, monitor changes, and support operational decisions.","highlights":["Weather and route analysis","Fuel and performance planning","Operational communication and monitoring","FAA certification applies to airline dispatchers"],"nextSteps":["Learn weather and flight planning fundamentals","Explore FAA-approved dispatcher programs","Build calm communication and analytical skills"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'flight-dispatch' or title = 'Flight Dispatch'));
