insert into public.career_paths (slug, title, summary, published, directory_content) select 'aircraft-maintenance', 'Aircraft Maintenance', 'Inspect, troubleshoot, and repair airframes, engines, avionics, and aircraft systems as an A&P mechanic or maintenance specialist.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"wrench","id":"","kind":"careers","slug":"aircraft-maintenance","title":"Aircraft Maintenance","summary":"Inspect, troubleshoot, and repair airframes, engines, avionics, and aircraft systems as an A&P mechanic or maintenance specialist.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/installation-maintenance-and-repair/aircraft-and-avionics-equipment-mechanics-and-technicians.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Aircraft and avionics technicians inspect, maintain, repair, and troubleshoot aircraft structures, engines, electrical systems, instruments, and electronic equipment.","highlights":["Safety-critical hands-on work","Airframe, powerplant, and avionics specializations","Technical-school and supervised-experience pathways","FAA mechanic certification may be required"],"nextSteps":["Visit an aviation maintenance program","Build mechanical and electrical skills","Learn about FAA A&P certification pathways"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'aircraft-maintenance' or title = 'Aircraft Maintenance'));
update public.career_paths set directory_content = '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"wrench","id":"","kind":"careers","slug":"aircraft-maintenance","title":"Aircraft Maintenance","summary":"Inspect, troubleshoot, and repair airframes, engines, avionics, and aircraft systems as an A&P mechanic or maintenance specialist.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/installation-maintenance-and-repair/aircraft-and-avionics-equipment-mechanics-and-technicians.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Aircraft and avionics technicians inspect, maintain, repair, and troubleshoot aircraft structures, engines, electrical systems, instruments, and electronic equipment.","highlights":["Safety-critical hands-on work","Airframe, powerplant, and avionics specializations","Technical-school and supervised-experience pathways","FAA mechanic certification may be required"],"nextSteps":["Visit an aviation maintenance program","Build mechanical and electrical skills","Learn about FAA A&P certification pathways"]}}'::jsonb where directory_content is null and (slug = 'aircraft-maintenance' or title = 'Aircraft Maintenance');
insert into public.career_paths (slug, title, summary, published, directory_content) select 'aeronautical-engineering', 'Aeronautical Engineering', 'Design and improve aircraft, systems, structures, interiors, and technology while balancing safety and performance.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"code","id":"","kind":"careers","slug":"aeronautical-engineering","title":"Aeronautical Engineering","summary":"Design and improve aircraft, systems, structures, interiors, and technology while balancing safety and performance.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/architecture-and-engineering/aerospace-engineers.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Aerospace engineers design, analyze, test, and improve aircraft, spacecraft, propulsion, structures, controls, and related systems.","highlights":["Mathematics, physics, design, and computing","Testing, simulation, and systems thinking","Usually requires an engineering degree","Work spans industry, research, defense, and government"],"nextSteps":["Strengthen math, physics, and coding","Join engineering or model-aircraft projects","Compare accredited aerospace and mechanical engineering programs"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'aeronautical-engineering' or title = 'Aeronautical Engineering'));
update public.career_paths set directory_content = '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"code","id":"","kind":"careers","slug":"aeronautical-engineering","title":"Aeronautical Engineering","summary":"Design and improve aircraft, systems, structures, interiors, and technology while balancing safety and performance.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/architecture-and-engineering/aerospace-engineers.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Aerospace engineers design, analyze, test, and improve aircraft, spacecraft, propulsion, structures, controls, and related systems.","highlights":["Mathematics, physics, design, and computing","Testing, simulation, and systems thinking","Usually requires an engineering degree","Work spans industry, research, defense, and government"],"nextSteps":["Strengthen math, physics, and coding","Join engineering or model-aircraft projects","Compare accredited aerospace and mechanical engineering programs"]}}'::jsonb where directory_content is null and (slug = 'aeronautical-engineering' or title = 'Aeronautical Engineering');
insert into public.career_paths (slug, title, summary, published, directory_content) select 'meteorology', 'Meteorology', 'Forecast the atmospheric conditions that affect every flight and help crews make safe operational decisions.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"cloud","id":"","kind":"careers","slug":"meteorology","title":"Meteorology","summary":"Forecast the atmospheric conditions that affect every flight and help crews make safe operational decisions.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/life-physical-and-social-science/atmospheric-scientists-including-meteorologists.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Meteorologists analyze the atmosphere and forecast conditions that directly influence routing, safety, performance, and operational decisions in aviation.","highlights":["Weather observation and forecasting","Data, models, radar, and satellite analysis","Science degree commonly required","Aviation forecasting requires operational awareness"],"nextSteps":["Study earth science, physics, and mathematics","Learn to read aviation weather products","Explore atmospheric-science degree programs"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'meteorology' or title = 'Meteorology'));
