insert into public.career_paths (slug, title, summary, published, directory_content) select 'cabin-crew-and-customer-experience', 'Cabin Crew & Customer Experience', 'Protect passenger safety and comfort in the cabin and support travelers throughout the airport journey.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"careers","slug":"cabin-crew-and-customer-experience","title":"Cabin Crew & Customer Experience","summary":"Protect passenger safety and comfort in the cabin and support travelers throughout the airport journey.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/transportation-and-material-moving/flight-attendants.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Flight attendants and customer-service teams protect safety, support passengers, respond to emergencies, and help the travel system operate smoothly.","highlights":["Passenger and cabin safety","Emergency procedures and first aid","Clear communication and service","Schedules may include nights, weekends, and travel"],"nextSteps":["Build customer-service experience","Practice communication and teamwork","Review airline hiring and training expectations"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'cabin-crew-and-customer-experience' or title = 'Cabin Crew & Customer Experience'));
