insert into public.career_paths (slug, title, summary, published, directory_content) select 'aerospace-medicine', 'Aerospace Medicine', 'Support the health, safety, and performance of people involved in air and space travel.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"user","id":"","kind":"careers","slug":"aerospace-medicine","title":"Aerospace Medicine","summary":"Support the health, safety, and performance of people involved in air and space travel.","tags":[],"info":{"officialUrl":"https://www.faa.gov/pilots/medical_certification","sourceLabel":"Federal Aviation Administration","overview":"Aerospace medicine focuses on the health, safety, and performance of people in aviation and space environments, including medical certification, human factors, and aeromedical care.","highlights":["Medicine connected to flight and space environments","Pilot medical certification and safety","Human performance and physiology","Requires professional medical education for physician roles"],"nextSteps":["Explore medicine, biology, and human factors","Learn what Aviation Medical Examiners do","Seek mentors in aerospace medicine"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'aerospace-medicine' or title = 'Aerospace Medicine'));
