insert into public.career_paths (slug, title, summary, published, directory_content) select 'aviation-law-and-business', 'Aviation Law & Business', 'Work where aviation meets regulation, insurance, airport management, business, policy, and risk.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"document","id":"","kind":"careers","slug":"aviation-law-and-business","title":"Aviation Law & Business","summary":"Work where aviation meets regulation, insurance, airport management, business, policy, and risk.","tags":[],"info":{"officialUrl":"https://www.faa.gov/about/office_org/headquarters_offices/agc","sourceLabel":"Federal Aviation Administration","overview":"Aviation law and business cover regulation, certification, insurance, airport and airline management, finance, policy, contracts, accident claims, and risk.","highlights":["Strong writing, research, analysis, and negotiation","Work across private companies and government","Legal careers require law school and licensing","Business roles span airlines, airports, and manufacturers"],"nextSteps":["Explore aviation business or policy courses","Follow FAA regulatory topics","Seek internships at airports, airlines, law firms, or aviation organizations"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'aviation-law-and-business' or title = 'Aviation Law & Business'));
