insert into public.career_paths (slug, title, summary, published, directory_content) select 'airline-pilot', 'Airline Pilot', 'Fly passengers for major or regional airlines while working through structured training, experience, and FAA certification requirements.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"airline-pilot","title":"Airline Pilot","summary":"Fly passengers for major or regional airlines while working through structured training, experience, and FAA certification requirements.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/transportation-and-material-moving/airline-and-commercial-pilots.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Airline pilots fly scheduled passenger and cargo routes after progressing through FAA certificates, ratings, flight experience, employer selection, and recurrent training.","highlights":["Major and regional airlines","ATP certification and experience","Crew coordination and decision-making"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'airline-pilot' or title = 'Airline Pilot'));
