insert into public.career_paths (slug, title, summary, published, directory_content) select 'corporate-charter-and-air-taxi-pilot', 'Corporate, Charter & Air Taxi Pilot', 'Fly people and business aircraft on flexible missions for companies, private owners, and charter operators.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"corporate-charter-and-air-taxi-pilot","title":"Corporate, Charter & Air Taxi Pilot","summary":"Fly people and business aircraft on flexible missions for companies, private owners, and charter operators.","tags":[],"info":{"officialUrl":"https://nbaa.org/professional-development/","sourceLabel":"NBAA","overview":"Corporate, charter, and air-taxi pilots operate business and on-demand flights for companies, private owners, and charter customers.","highlights":["Business aircraft operations","Flexible routes and schedules","Customer service and safety"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'corporate-charter-and-air-taxi-pilot' or title = 'Corporate, Charter & Air Taxi Pilot'));
