insert into public.career_paths (slug, title, summary, published, directory_content) select 'cargo-and-ferry-pilot', 'Cargo & Ferry Pilot', 'Move packages or deliver aircraft between owners, operators, maintenance facilities, and destinations around the world.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"cargo-and-ferry-pilot","title":"Cargo & Ferry Pilot","summary":"Move packages or deliver aircraft between owners, operators, maintenance facilities, and destinations around the world.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/transportation-and-material-moving/airline-and-commercial-pilots.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Cargo pilots transport freight, while ferry pilots reposition or deliver aircraft between owners, operators, and maintenance locations.","highlights":["Freight and logistics","Aircraft delivery","Weather and route planning"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'cargo-and-ferry-pilot' or title = 'Cargo & Ferry Pilot'));
