insert into public.career_paths (slug, title, summary, published, directory_content) select 'government-military-and-law-enforcement-pilot', 'Government, Military & Law Enforcement Pilot', 'Fly airplanes, helicopters, or uncrewed aircraft in public service, national defense, emergency response, and law enforcement.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"government-military-and-law-enforcement-pilot","title":"Government, Military & Law Enforcement Pilot","summary":"Fly airplanes, helicopters, or uncrewed aircraft in public service, national defense, emergency response, and law enforcement.","tags":[],"info":{"officialUrl":"https://www.faa.gov/jobs/career_fields/aviation_careers","sourceLabel":"Federal Aviation Administration","overview":"Public-service pilots fly for military branches and government agencies in defense, patrol, transport, research, rescue, and law-enforcement missions.","highlights":["Public service","Airplane, helicopter, and UAS roles","Agency-specific selection and training"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'government-military-and-law-enforcement-pilot' or title = 'Government, Military & Law Enforcement Pilot'));
