insert into public.career_paths (slug, title, summary, published, directory_content) select 'firefighting-and-agricultural-pilot', 'Firefighting & Agricultural Pilot', 'Use specialized aircraft at low altitude to fight wildfires, protect crops, and support land-management missions.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"firefighting-and-agricultural-pilot","title":"Firefighting & Agricultural Pilot","summary":"Use specialized aircraft at low altitude to fight wildfires, protect crops, and support land-management missions.","tags":[],"info":{"officialUrl":"https://www.faa.gov/pilots","sourceLabel":"Federal Aviation Administration","overview":"Firefighting and agricultural pilots use specialized aircraft at low altitude for wildfire suppression, crop protection, and land-management work.","highlights":["Specialized low-altitude flying","Seasonal and mission-driven work","Advanced experience and training"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'firefighting-and-agricultural-pilot' or title = 'Firefighting & Agricultural Pilot'));
