insert into public.career_paths (slug, title, summary, published, directory_content) select 'air-tour-media-and-banner-pilot', 'Air Tour, Media & Banner Pilot', 'Fly sightseeing, news, patrol, photography, and aerial advertising missions that require precision and strong local knowledge.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"air-tour-media-and-banner-pilot","title":"Air Tour, Media & Banner Pilot","summary":"Fly sightseeing, news, patrol, photography, and aerial advertising missions that require precision and strong local knowledge.","tags":[],"info":{"officialUrl":"https://www.faa.gov/pilots","sourceLabel":"Federal Aviation Administration","overview":"These commercial pilots fly sightseeing, news, patrol, photography, traffic-reporting, and aerial-advertising missions.","highlights":["Local-area expertise","Commercial pilot pathway","Precision and communication"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'air-tour-media-and-banner-pilot' or title = 'Air Tour, Media & Banner Pilot'));
