insert into public.career_paths (slug, title, summary, published, directory_content) select 'test-airshow-and-space-pilot', 'Test, Airshow & Space Pilot', 'Evaluate new aircraft, demonstrate advanced flying, compete in aerobatics, or help shape future commercial spaceflight.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"careers","slug":"test-airshow-and-space-pilot","title":"Test, Airshow & Space Pilot","summary":"Evaluate new aircraft, demonstrate advanced flying, compete in aerobatics, or help shape future commercial spaceflight.","tags":[],"info":{"officialUrl":"https://www.nasa.gov/humans-in-space/astronauts/become-an-astronaut/","sourceLabel":"NASA","overview":"Test pilots evaluate aircraft, airshow pilots demonstrate precision flying, and future space pilots operate at the edge of aviation and human spaceflight.","highlights":["Flight test and evaluation","Aerobatic demonstration","Spaceflight and research pathways"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'test-airshow-and-space-pilot' or title = 'Test, Airshow & Space Pilot'));
