insert into public.career_paths (slug, title, summary, published, directory_content) select 'airport-customer-service', 'Airport Customer Service', 'Guide travelers from check-in through boarding, solve problems, and support safe, welcoming airport operations.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"careers","slug":"airport-customer-service","title":"Airport Customer Service","summary":"Guide travelers from check-in through boarding, solve problems, and support safe, welcoming airport operations.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/transportation-and-material-moving/home.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Airport customer-service professionals help travelers with check-in, boarding, rebooking, accessibility, baggage, and day-to-day travel problems.","highlights":["Passenger support","Airline and airport operations","Communication and problem-solving"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'airport-customer-service' or title = 'Airport Customer Service'));
