insert into public.career_paths (slug, title, summary, published, directory_content) select 'airport-emergency-response', 'Airport Emergency Response', 'Respond to aircraft incidents, medical emergencies, fires, alarms, and other hazards across an airport campus.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"careers","slug":"airport-emergency-response","title":"Airport Emergency Response","summary":"Respond to aircraft incidents, medical emergencies, fires, alarms, and other hazards across an airport campus.","tags":[],"info":{"officialUrl":"https://www.faa.gov/airports/airport_safety/aircraft_rescue_fire_fighting","sourceLabel":"Federal Aviation Administration","overview":"Aircraft rescue and firefighting teams prepare for and respond to aircraft incidents, fires, medical calls, alarms, and airport emergencies.","highlights":["Aircraft rescue and firefighting","Medical and emergency response","Specialized airport training"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'airport-emergency-response' or title = 'Airport Emergency Response'));
