insert into public.career_paths (slug, title, summary, published, directory_content) select 'airport-police-and-security', 'Airport Police & Security', 'Protect airport facilities and travelers through patrol, investigation, traffic control, security, and emergency response.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"careers","slug":"airport-police-and-security","title":"Airport Police & Security","summary":"Protect airport facilities and travelers through patrol, investigation, traffic control, security, and emergency response.","tags":[],"info":{"officialUrl":"https://www.tsa.gov/about/jobs-at-tsa","sourceLabel":"Transportation Security Administration","overview":"Airport police and security teams protect people, aircraft, terminals, roads, and restricted areas through patrol, screening, investigation, and emergency response.","highlights":["Law enforcement and security","Airport-campus operations","Public safety"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'airport-police-and-security' or title = 'Airport Police & Security'));
