insert into public.career_paths (slug, title, summary, published, directory_content) select 'avionics-technician', 'Avionics Technician', 'Install, inspect, troubleshoot, and repair the electronic instruments, communications, navigation, and control systems inside aircraft.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"wrench","id":"","kind":"careers","slug":"avionics-technician","title":"Avionics Technician","summary":"Install, inspect, troubleshoot, and repair the electronic instruments, communications, navigation, and control systems inside aircraft.","tags":[],"info":{"officialUrl":"https://www.bls.gov/ooh/installation-maintenance-and-repair/aircraft-and-avionics-equipment-mechanics-and-technicians.htm","sourceLabel":"U.S. Bureau of Labor Statistics","overview":"Avionics technicians install, test, maintain, and repair aircraft communications, navigation, radar, instruments, and electronic control systems.","highlights":["Electronics and troubleshooting","Aircraft navigation and communication","Technical training and certification"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'avionics-technician' or title = 'Avionics Technician'));
