insert into public.career_paths (slug, title, summary, published, directory_content) select 'aviation-training-and-education', 'Aviation Training & Education', 'Design curricula and teach pilots, mechanics, controllers, and other aviation professionals in schools and training centers.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"careers","slug":"aviation-training-and-education","title":"Aviation Training & Education","summary":"Design curricula and teach pilots, mechanics, controllers, and other aviation professionals in schools and training centers.","tags":[],"info":{"officialUrl":"https://www.faa.gov/training_testing/training","sourceLabel":"Federal Aviation Administration","overview":"Aviation educators design and deliver training for pilots, mechanics, dispatchers, controllers, cabin crews, and other professionals.","highlights":["Teaching and curriculum design","Schools, colleges, and industry centers","Safety and standards"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'aviation-training-and-education' or title = 'Aviation Training & Education'));
