insert into public.career_paths (slug, title, summary, published, directory_content) select 'space-science-and-astronautics', 'Space Science & Astronautics', 'Study spacecraft, missions, planetary science, space systems, and the environments beyond Earth.', true, '{"published":true,"partner":false,"order":0,"award":"","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"spacecraft","id":"","kind":"careers","slug":"space-science-and-astronautics","title":"Space Science & Astronautics","summary":"Study spacecraft, missions, planetary science, space systems, and the environments beyond Earth.","tags":[],"info":{"officialUrl":"https://stemgateway.nasa.gov/public/s/explore-opportunities","sourceLabel":"NASA STEM Gateway","overview":"Space scientists and astronautics professionals study missions, spacecraft, planetary environments, propulsion, remote sensing, and the systems needed beyond Earth.","highlights":["Spacecraft and mission systems","Planetary and space science","Engineering, data, and research"],"nextSteps":["Review the current official requirements","Confirm eligibility, dates, and location details","Save the opportunity and prepare early"]}}'::jsonb where not exists (select 1 from public.career_paths where (slug = 'space-science-and-astronautics' or title = 'Space Science & Astronautics'));
