insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'eaa-ray-aviation-scholarship', 'EAA Ray Aviation Scholarship', 'The Ray Aviation Scholarship is a merit-based flight-training program funded by the Ray Foundation, managed by EAA, and administered through local EAA chapters. Candidates work through a participating chapter rather than applying directly to the national program.', true, '{"published":true,"partner":false,"order":0,"award":"Up to $12,000*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"scholarships","slug":"eaa-ray-aviation-scholarship","title":"EAA Ray Aviation Scholarship","summary":"The Ray Aviation Scholarship is a merit-based flight-training program funded by the Ray Foundation, managed by EAA, and administered through local EAA chapters. Candidates work through a participating chapter rather than applying directly to the national program.","tags":["Ages 16–19 · Chapter nomination"],"info":{"officialUrl":"https://www.eaa.org/eaa/eaa-chapters/eaa-chapter-resources/chapter-programs-and-activities/ray-aviation-scholarship-fund","sourceLabel":"EAA","overview":"The Ray Aviation Scholarship is a merit-based flight-training program funded by the Ray Foundation, managed by EAA, and administered through local EAA chapters. Candidates work through a participating chapter rather than applying directly to the national program.","highlights":["Up to $12,000 toward flight training","Local EAA chapter nomination and mentoring","Designed for highly engaged young aviators","Training milestones and chapter participation"],"nextSteps":["Find and participate in a local EAA chapter","Ask the chapter scholarship coordinator about nominations","Prepare to explain your goals, commitment, and training plan"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'eaa-ray-aviation-scholarship' or title = 'EAA Ray Aviation Scholarship') and type = 'scholarship');
