insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'harrison-ford-scholarship', 'Harrison Ford Scholarship', 'An EAA scholarship associated with supporting Young Eagles as they pursue flight training, aviation education, or technical pathways. Availability and criteria may vary by cycle.', true, '{"published":true,"partner":false,"order":0,"award":"Varies*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"scholarships","slug":"harrison-ford-scholarship","title":"Harrison Ford Scholarship","summary":"An EAA scholarship associated with supporting Young Eagles as they pursue flight training, aviation education, or technical pathways. Availability and criteria may vary by cycle.","tags":["Young Eagles · Financial need considered"],"info":{"officialUrl":"https://www.eaa.org/eaa/learn-to-fly/scholarships","sourceLabel":"EAA Scholarships","overview":"An EAA scholarship associated with supporting Young Eagles as they pursue flight training, aviation education, or technical pathways. Availability and criteria may vary by cycle.","highlights":["Young Eagles connection","Aviation training or education focus","Financial need may be considered"],"nextSteps":["Review the current EAA scholarship cycle","Document your Young Eagles and chapter involvement","Explain how the award advances your aviation goal"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'harrison-ford-scholarship' or title = 'Harrison Ford Scholarship') and type = 'scholarship');
