insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'adapt-to-fly-scholarship', 'Adapt to Fly Scholarship', 'Adapt to Fly was created to expand aviation access for people with disabilities who can meet the applicable operational and medical eligibility requirements.', true, '{"published":true,"partner":false,"order":0,"award":"Varies*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"path","id":"","kind":"scholarships","slug":"adapt-to-fly-scholarship","title":"Adapt to Fly Scholarship","summary":"Adapt to Fly was created to expand aviation access for people with disabilities who can meet the applicable operational and medical eligibility requirements.","tags":["Pilots with disabilities · Eligibility applies"],"info":{"officialUrl":"https://www.eaa.org/eaa/learn-to-fly/scholarships","sourceLabel":"EAA Scholarships","overview":"Adapt to Fly was created to expand aviation access for people with disabilities who can meet the applicable operational and medical eligibility requirements.","highlights":["Disability-focused aviation access","Training toward an eligible pilot certificate","Individual aircraft-control and medical requirements apply"],"nextSteps":["Review current EAA availability","Discuss medical eligibility with qualified professionals","Identify an accessible training environment"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'adapt-to-fly-scholarship' or title = 'Adapt to Fly Scholarship') and type = 'scholarship');
