insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'civil-air-patrol-cadet-wings', 'Civil Air Patrol Cadet Wings', 'Cadet Wings is Civil Air Patrol’s merit-based pathway helping qualified cadets progress toward a Private Pilot Certificate through approved training and structured support.', true, '{"published":true,"partner":false,"order":0,"award":"Funded training*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"cap","id":"","kind":"scholarships","slug":"civil-air-patrol-cadet-wings","title":"Civil Air Patrol Cadet Wings","summary":"Cadet Wings is Civil Air Patrol’s merit-based pathway helping qualified cadets progress toward a Private Pilot Certificate through approved training and structured support.","tags":["CAP cadets · Private pilot pathway"],"info":{"officialUrl":"https://www.gocivilairpatrol.com/programs/cadets/cadetinvest/cadet-wings","sourceLabel":"Civil Air Patrol","overview":"Cadet Wings is Civil Air Patrol’s merit-based pathway helping qualified cadets progress toward a Private Pilot Certificate through approved training and structured support.","highlights":["For eligible Civil Air Patrol cadets","Structured private-pilot training pathway","Training may occur locally or through approved providers","Commitment and cadet performance matter"],"nextSteps":["Join and actively participate in CAP","Review current Cadet Wings prerequisites","Build a strong record in leadership and aerospace activities"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'civil-air-patrol-cadet-wings' or title = 'Civil Air Patrol Cadet Wings') and type = 'scholarship');
