insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'aopa-foundation-scholarship', 'AOPA Foundation Scholarship', 'AOPA Foundation scholarships support eligible members pursuing primary flight training, advanced certificates and ratings, aviation maintenance, and other aviation career pathways.', true, '{"published":true,"partner":false,"order":0,"award":"$2,500+*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"scholarships","slug":"aopa-foundation-scholarship","title":"AOPA Foundation Scholarship","summary":"AOPA Foundation scholarships support eligible members pursuing primary flight training, advanced certificates and ratings, aviation maintenance, and other aviation career pathways.","tags":["Age 16+ · Student pilot certificate"],"info":{"officialUrl":"https://www.aopa.org/training-and-safety/students/aopa-flight-training-scholarships","sourceLabel":"AOPA Foundation","overview":"AOPA Foundation scholarships support eligible members pursuing primary flight training, advanced certificates and ratings, aviation maintenance, and other aviation career pathways.","highlights":["Multiple awards through one current program","AOPA membership and residency requirements apply","Primary and advanced training pathways","Application cycles and award amounts change"],"nextSteps":["Join or verify AOPA membership","Review the active application window","Prepare essays, references, and a practical training plan"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'aopa-foundation-scholarship' or title = 'AOPA Foundation Scholarship') and type = 'scholarship');
