insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'aopa-high-school-flight-training', 'AOPA High School Flight Training', 'AOPA periodically offers flight-training awards directed toward high-school students. The current AOPA Foundation page is the authoritative place to confirm which student awards are active.', true, '{"published":true,"partner":false,"order":0,"award":"Up to $10,000*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"school","id":"","kind":"scholarships","slug":"aopa-high-school-flight-training","title":"AOPA High School Flight Training","summary":"AOPA periodically offers flight-training awards directed toward high-school students. The current AOPA Foundation page is the authoritative place to confirm which student awards are active.","tags":["Ages 16–18 · GPA and test requirements"],"info":{"officialUrl":"https://www.aopa.org/training-and-safety/students/aopa-flight-training-scholarships","sourceLabel":"AOPA Foundation","overview":"AOPA periodically offers flight-training awards directed toward high-school students. The current AOPA Foundation page is the authoritative place to confirm which student awards are active.","highlights":["High-school student focus","Private pilot training pathway","Academic and knowledge-test criteria may apply","Current cycle determines available awards"],"nextSteps":["Review current AOPA scholarship listings","Confirm age, membership, and academic criteria","Plan for the FAA knowledge test if required"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'aopa-high-school-flight-training' or title = 'AOPA High School Flight Training') and type = 'scholarship');
