insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'leroy-w-homer-jr-scholarship', 'LeRoy W. Homer Jr. Scholarship', 'The foundation supports dedicated young people pursuing a Private Pilot Certificate independently rather than as part of a college aviation degree program.', true, '{"published":true,"partner":false,"order":0,"award":"Training support*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"scholarships","slug":"leroy-w-homer-jr-scholarship","title":"LeRoy W. Homer Jr. Scholarship","summary":"The foundation supports dedicated young people pursuing a Private Pilot Certificate independently rather than as part of a college aviation degree program.","tags":["Ages 16–23 · Private pilot training"],"info":{"officialUrl":"https://leroywhomerjr.org/scholarships/","sourceLabel":"The LeRoy W. Homer Jr. Foundation","overview":"The foundation supports dedicated young people pursuing a Private Pilot Certificate independently rather than as part of a college aviation degree program.","highlights":["Private pilot training focus","Youth eligibility requirements","Independent flight-training pathway","Annual application window"],"nextSteps":["Review the foundation’s current criteria","Identify a flight school and realistic budget","Prepare a compelling application about your aviation commitment"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'leroy-w-homer-jr-scholarship' or title = 'LeRoy W. Homer Jr. Scholarship') and type = 'scholarship');
