insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'the-ninety-nines-first-wings', 'The Ninety-Nines First Wings', 'First Wings provides milestone-based assistance to eligible Student Pilot members of The Ninety-Nines who are working toward their first pilot certificate.', true, '{"published":true,"partner":false,"order":0,"award":"Up to $6,000*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"people","id":"","kind":"scholarships","slug":"the-ninety-nines-first-wings","title":"The Ninety-Nines First Wings","summary":"First Wings provides milestone-based assistance to eligible Student Pilot members of The Ninety-Nines who are working toward their first pilot certificate.","tags":["Student pilot members · Milestone based"],"info":{"officialUrl":"https://www.ninety-nines.org/scholarships.htm","sourceLabel":"The Ninety-Nines","overview":"First Wings provides milestone-based assistance to eligible Student Pilot members of The Ninety-Nines who are working toward their first pilot certificate.","highlights":["Up to $6,000 through training milestones","Student Pilot membership period required","Recent logged flight time required","Applications are typically offered twice yearly"],"nextSteps":["Review Student Pilot membership","Track flight time and training milestones","Confirm the next official deadline"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'the-ninety-nines-first-wings' or title = 'The Ninety-Nines First Wings') and type = 'scholarship');
