insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'ssa-discover-soaring-scholarship', 'SSA Discover Soaring Scholarship', 'Discover Soaring introduces young non-pilots to gliding through training credits and other awards sponsored through a participating U.S. soaring organization.', true, '{"published":true,"partner":false,"order":0,"award":"Training awards*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"globe","id":"","kind":"scholarships","slug":"ssa-discover-soaring-scholarship","title":"SSA Discover Soaring Scholarship","summary":"Discover Soaring introduces young non-pilots to gliding through training credits and other awards sponsored through a participating U.S. soaring organization.","tags":["Young non-pilots · Glider training"],"info":{"officialUrl":"https://www.ssa.org/discover-scholarship/","sourceLabel":"Soaring Society of America","overview":"Discover Soaring introduces young non-pilots to gliding through training credits and other awards sponsored through a participating U.S. soaring organization.","highlights":["For young non-pilots","Glider training credits","A sponsoring soaring organization is important","Interest, financial need, and promise are considered"],"nextSteps":["Visit a gliderport","Find a sponsoring club or commercial operator","Explain why soaring fits your goals"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'ssa-discover-soaring-scholarship' or title = 'SSA Discover Soaring Scholarship') and type = 'scholarship');
