insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'dennis-purduski-flight-training-scholarship', 'Dennis Purduski Flight Training Scholarship', 'This SSA scholarship supports pre-solo youth members with direct glider flight-training expenses and emphasizes commitment, a clear plan, community involvement, and mentoring.', true, '{"published":true,"partner":false,"order":0,"award":"Up to $2,000*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"plane","id":"","kind":"scholarships","slug":"dennis-purduski-flight-training-scholarship","title":"Dennis Purduski Flight Training Scholarship","summary":"This SSA scholarship supports pre-solo youth members with direct glider flight-training expenses and emphasizes commitment, a clear plan, community involvement, and mentoring.","tags":["SSA members ages 13–19 · Pre-solo"],"info":{"officialUrl":"https://www.ssa.org/dennis-purduski-flight-training-scholarship/","sourceLabel":"Soaring Society of America","overview":"This SSA scholarship supports pre-solo youth members with direct glider flight-training expenses and emphasizes commitment, a clear plan, community involvement, and mentoring.","highlights":["Ages 13–19 and pre-solo","Up to $2,000 in flight-training support","SSA membership required","Personal statement and recommendations"],"nextSteps":["Join SSA and a local soaring community","Define specific training goals","Ask mentors for recommendations early"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'dennis-purduski-flight-training-scholarship' or title = 'Dennis Purduski Flight Training Scholarship') and type = 'scholarship');
