insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'eaa-post-secondary-scholarship', 'EAA Post-Secondary Scholarship', 'EAA post-secondary scholarships support aviation-related college and technical study, including engineering, maintenance, air traffic control, aviation business, professional flight, and related STEM fields.', true, '{"published":true,"partner":false,"order":0,"award":"Varies*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"school","id":"","kind":"scholarships","slug":"eaa-post-secondary-scholarship","title":"EAA Post-Secondary Scholarship","summary":"EAA post-secondary scholarships support aviation-related college and technical study, including engineering, maintenance, air traffic control, aviation business, professional flight, and related STEM fields.","tags":["Aviation degree or technical education"],"info":{"officialUrl":"https://www.eaa.org/eaa/learn-to-fly/scholarships","sourceLabel":"EAA Scholarships","overview":"EAA post-secondary scholarships support aviation-related college and technical study, including engineering, maintenance, air traffic control, aviation business, professional flight, and related STEM fields.","highlights":["College and technical education","Many aviation fields can qualify","Current and incoming students may apply","One EAA process may match multiple awards"],"nextSteps":["Confirm your program is aviation related","Review EAA’s current application dates","Show how your education leads to active aviation involvement"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'eaa-post-secondary-scholarship' or title = 'EAA Post-Secondary Scholarship') and type = 'scholarship');
