insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'ssa-kolstad-award', 'SSA Kolstad Award', 'The Kolstad Award supports college-level academic study for accomplished young soaring pilots who demonstrate achievement, service, and strong educational and career goals.', true, '{"published":true,"partner":false,"order":0,"award":"Up to $10,000*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"school","id":"","kind":"scholarships","slug":"ssa-kolstad-award","title":"SSA Kolstad Award","summary":"The Kolstad Award supports college-level academic study for accomplished young soaring pilots who demonstrate achievement, service, and strong educational and career goals.","tags":["Ages 14–25 · College study"],"info":{"officialUrl":"https://www.ssa.org/soaring-scholarships/","sourceLabel":"Soaring Society of America","overview":"The Kolstad Award supports college-level academic study for accomplished young soaring pilots who demonstrate achievement, service, and strong educational and career goals.","highlights":["Up to $10,000 toward academic study","Competitive award for ages 14–25","Soaring achievement and service matter","Funds are paid toward education"],"nextSteps":["Review current SSA requirements","Document soaring achievement and service","Request detailed recommendations"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'ssa-kolstad-award' or title = 'SSA Kolstad Award') and type = 'scholarship');
