insert into public.opportunities (slug, title, summary, published, directory_content, type) select 'astronaut-scholarship', 'Astronaut Scholarship', 'The Astronaut Scholarship Foundation supports exceptional U.S. undergraduate STEM students who show significant research, creativity, leadership, and potential to advance science and technology. Students must be nominated by a participating university.', true, '{"published":true,"partner":false,"order":0,"award":"Up to $15,000*","deadline":"","location":"","education":"","logoUrl":"","category":"","icon":"school","id":"","kind":"scholarships","slug":"astronaut-scholarship","title":"Astronaut Scholarship","summary":"The Astronaut Scholarship Foundation supports exceptional U.S. undergraduate STEM students who show significant research, creativity, leadership, and potential to advance science and technology. Students must be nominated by a participating university.","tags":["College juniors/seniors · STEM research"],"info":{"officialUrl":"https://www.astronautscholarship.org/programs/astronaut-scholarship/","sourceLabel":"Astronaut Scholarship Foundation","overview":"The Astronaut Scholarship Foundation supports exceptional U.S. undergraduate STEM students who show significant research, creativity, leadership, and potential to advance science and technology. Students must be nominated by a participating university.","highlights":["Up to $15,000","For eligible juniors and seniors in STEM","Faculty nomination through a participating university","Includes mentoring, networking, and professional development"],"nextSteps":["Confirm that your university participates","Speak with faculty or the university liaison","Build a strong record of research and work beyond the classroom"]}}'::jsonb, 'scholarship' where not exists (select 1 from public.opportunities where (slug = 'astronaut-scholarship' or title = 'Astronaut Scholarship') and type = 'scholarship');
